CREATE TABLE legui_private.tenant_ordering(
 tenant_id uuid PRIMARY KEY REFERENCES public.tenants(id),timezone text NOT NULL DEFAULT 'America/Argentina/Buenos_Aires',schedule_enabled boolean NOT NULL DEFAULT false,paused boolean NOT NULL DEFAULT false,pause_until timestamptz,
 pending_minutes integer NOT NULL DEFAULT 15 CHECK(pending_minutes BETWEEN 5 AND 60),prep_min integer NOT NULL DEFAULT 20 CHECK(prep_min BETWEEN 1 AND 180),prep_max integer NOT NULL DEFAULT 35 CHECK(prep_max BETWEEN prep_min AND 240),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE legui_private.ordering_periods(tenant_id uuid NOT NULL REFERENCES public.tenants(id),day integer NOT NULL CHECK(day BETWEEN 0 AND 6),opens integer NOT NULL CHECK(opens BETWEEN 0 AND 1439),closes integer NOT NULL CHECK(closes BETWEEN 1 AND 1440 AND closes>opens),PRIMARY KEY(tenant_id,day,opens,closes));
CREATE FUNCTION legui_private.tenant_receiving(local_id uuid,at_time timestamptz DEFAULT clock_timestamp()) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT coalesce((SELECT t.active AND t.menu_published AND t.ordering_enabled AND b.suspended_at IS NULL AND b.closed_at IS NULL AND NOT(coalesce(c.paused,false) AND(c.pause_until IS NULL OR c.pause_until>at_time)) AND(NOT coalesce(c.schedule_enabled,false) OR EXISTS(SELECT 1 FROM legui_private.ordering_periods p WHERE p.tenant_id=t.id AND p.day=extract(dow FROM at_time AT TIME ZONE coalesce(c.timezone,'America/Argentina/Buenos_Aires'))::integer AND p.opens<=extract(hour FROM at_time AT TIME ZONE c.timezone)::integer*60+extract(minute FROM at_time AT TIME ZONE c.timezone)::integer AND p.closes>extract(hour FROM at_time AT TIME ZONE c.timezone)::integer*60+extract(minute FROM at_time AT TIME ZONE c.timezone)::integer)) FROM public.tenants t JOIN public.brands b ON b.id=t.brand_id LEFT JOIN legui_private.tenant_ordering c ON c.tenant_id=t.id WHERE t.id=local_id),false)
$$;
ALTER TABLE public.orders ADD COLUMN pending_deadline timestamptz,ADD COLUMN ended_reason text NOT NULL DEFAULT '',ADD COLUMN prep_min integer,ADD COLUMN prep_max integer,ADD COLUMN estimated_ready_at timestamptz;
CREATE INDEX orders_pending_deadline ON public.orders(pending_deadline) WHERE pending_deadline IS NOT NULL;
CREATE FUNCTION legui_private.set_order_expectations() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF NEW.channel='web' AND NEW.payment_environment='production' THEN
 SELECT clock_timestamp()+make_interval(mins=>coalesce(c.pending_minutes,15)),coalesce(c.prep_min,20),coalesce(c.prep_max,35) INTO NEW.pending_deadline,NEW.prep_min,NEW.prep_max FROM public.tenants t LEFT JOIN legui_private.tenant_ordering c ON c.tenant_id=t.id WHERE t.id=NEW.tenant_id;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER orders_expectations BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION legui_private.set_order_expectations();
CREATE FUNCTION legui_private.expire_pending_orders() RETURNS integer LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE changed integer;BEGIN
 WITH picked AS(SELECT o.id FROM public.orders o JOIN public.order_statuses_lookup s ON s.id=o.order_status_id WHERE s.code='pending' AND o.pending_deadline<clock_timestamp() AND o.total_paid=0 AND NOT EXISTS(SELECT 1 FROM legui_private.mp_checkouts x WHERE x.order_id=o.id AND x.state IN ('prepared','submitting','created','review') AND(x.expires_at>clock_timestamp() OR x.state IN ('submitting','review'))) ORDER BY o.pending_deadline LIMIT 50 FOR UPDATE OF o SKIP LOCKED)
 UPDATE public.orders o SET order_status_id=(SELECT id FROM public.order_statuses_lookup WHERE code='canceled'),ended_reason='El local no confirmó el pedido dentro del plazo disponible' FROM picked WHERE o.id=picked.id;
 GET DIAGNOSTICS changed=ROW_COUNT;RETURN changed;END$$;
-- Existing order-ID listeners remain compatible. Tenant keys enable staff inboxes.
CREATE OR REPLACE FUNCTION legui_private.notify_order_stream() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE local_id uuid;BEGIN
 IF TG_TABLE_NAME='orders' THEN PERFORM pg_notify('legui_order_changed',NEW.id::text);local_id:=NEW.tenant_id;
 ELSE IF NEW.order_id IS NOT NULL THEN PERFORM pg_notify('legui_order_changed',NEW.order_id::text);local_id:=NEW.tenant_id;END IF;END IF;
 IF local_id IS NOT NULL THEN PERFORM pg_notify('legui_order_changed','tenant:'||local_id::text);END IF;RETURN NEW;END$$;
CREATE TRIGGER order_stream_created AFTER INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION legui_private.notify_order_stream();
CREATE TABLE legui_private.order_mail_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id),version bigint NOT NULL,status text NOT NULL,paid numeric NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),processed_at timestamptz,outbox_id uuid REFERENCES legui_private.mail_outbox(id),UNIQUE(order_id,version));
CREATE FUNCTION legui_private.capture_order_mail() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF NEW.channel='web' AND NEW.payment_environment='production' THEN INSERT INTO legui_private.order_mail_events(order_id,version,status,paid) SELECT NEW.id,NEW.version,s.code,NEW.total_paid FROM public.order_statuses_lookup s WHERE s.id=NEW.order_status_id ON CONFLICT DO NOTHING;END IF;RETURN NEW;END$$;
CREATE TRIGGER order_mail_created AFTER INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION legui_private.capture_order_mail();
CREATE TRIGGER order_mail_changed AFTER UPDATE OF order_status_id,total_paid ON public.orders FOR EACH ROW WHEN(OLD.order_status_id IS DISTINCT FROM NEW.order_status_id OR OLD.total_paid IS DISTINCT FROM NEW.total_paid) EXECUTE FUNCTION legui_private.capture_order_mail();
CREATE TABLE legui_private.newsletter_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brand_id uuid NOT NULL REFERENCES public.brands(id),subject text NOT NULL CHECK(length(subject) BETWEEN 3 AND 120),body_cipher text NOT NULL,segment text NOT NULL CHECK(segment IN ('all','frequent','recover','new')),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','queued','completed','canceled')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),sent_at timestamptz);
CREATE TABLE legui_private.newsletter_recipients(campaign_id uuid NOT NULL REFERENCES legui_private.newsletter_campaigns(id),shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),recipient_email text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','queued','skipped')),outbox_id uuid REFERENCES legui_private.mail_outbox(id),PRIMARY KEY(campaign_id,shopper_id));
CREATE TABLE legui_private.newsletter_unsubscribes(digest text PRIMARY KEY CHECK(digest ~ '^[a-f0-9]{64}$'),brand_id uuid NOT NULL REFERENCES public.brands(id),shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '1 year');
ALTER TABLE legui_private.mail_outbox ADD COLUMN campaign_id uuid REFERENCES legui_private.newsletter_campaigns(id),ADD COLUMN shopper_id uuid REFERENCES legui_private.shoppers(id),ADD COLUMN brand_id uuid REFERENCES public.brands(id),ADD COLUMN order_event_id uuid REFERENCES legui_private.order_mail_events(id);
CREATE UNIQUE INDEX campaign_mail_once ON legui_private.mail_outbox(campaign_id,shopper_id) WHERE campaign_id IS NOT NULL;
CREATE UNIQUE INDEX event_mail_once ON legui_private.mail_outbox(order_event_id) WHERE order_event_id IS NOT NULL;
CREATE FUNCTION legui_private.mail_eligible(mail_id uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM legui_private.mail_outbox m WHERE m.id=mail_id AND(m.campaign_id IS NULL OR EXISTS(SELECT 1 FROM legui_private.newsletter_campaigns c JOIN public.brands b ON b.id=c.brand_id AND b.closed_at IS NULL AND b.suspended_at IS NULL JOIN legui_private.shoppers p ON p.id=m.shopper_id AND p.active AND p.email_verified AND p.email=m.recipient JOIN legui_private.shopper_preferences pref ON pref.shopper_id=p.id AND pref.brand_id=c.brand_id AND pref.newsletter WHERE c.id=m.campaign_id AND c.state IN ('queued','completed') AND(c.segment='all' OR pref.personalization))) AND(m.order_event_id IS NULL OR EXISTS(SELECT 1 FROM legui_private.order_mail_events e JOIN public.orders o ON o.id=e.order_id JOIN public.order_statuses_lookup s ON s.id=o.order_status_id JOIN legui_private.shoppers p ON p.id=m.shopper_id AND p.active AND p.email_verified AND p.email=m.recipient WHERE e.id=m.order_event_id AND e.status=s.code AND e.paid=o.total_paid)))
$$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['tenant_ordering','ordering_periods','order_mail_events','newsletter_campaigns','newsletter_recipients','newsletter_unsubscribes'] LOOP EXECUTE format('ALTER TABLE legui_private.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('REVOKE ALL ON legui_private.%I FROM PUBLIC,anon,authenticated,service_role',n);END LOOP;END$$;
REVOKE ALL ON FUNCTION legui_private.tenant_receiving(uuid,timestamptz),legui_private.set_order_expectations(),legui_private.expire_pending_orders(),legui_private.capture_order_mail(),legui_private.mail_eligible(uuid) FROM PUBLIC,anon,authenticated,service_role;
